{"code": "from hermes_tools import terminal

base = "/home/zhouhuijuan1987/wiki/youtube-video-research-wiki/wiki"

# Extract all wikilinks
result = terminal(f"cd '{base}' && grep -rho '\\[\\[[^]]*\\]\\]' sources/ entities/ concepts/ comparisons/ overview/ --include='*.md' | sort -u")
links = set()
for line in result["output"].strip().split("\n"):
    # Extract content between [[ and ]]
    link = line.strip("[]")
    links.add(link)

print(f"Total unique wikilinks: {len(links)}")

# Directories to check
dirs = ["sources", "entities", "concepts", "comparisons", "overview"]

missing = []
for link in sorted(links):
    found = False
    for d in dirs:
        r = terminal(f"[ -f '{base}/{d}/{link}.md' ] && echo 'FOUND' || echo 'NOTFOUND'", timeout=5)
        if "FOUND" in r["output"]:
            found = True
            break
    if not found:
        missing.append(link)

if missing:
    print(f"\n❌ Missing wikilinks ({len(missing)}):")
    for m in missing:
        print(f"  - [[{m}]]")
else:
    print("\n✅ No dead links found!")
"}

